mapper.select:
select distinct u.id, u.account_name as accountName, u.preferred_locale as preferredLocale from cm_users u left join cm_user_preferences p on p.user_id = u.id left join cm_user_memberships m on m.user_id = u.id and m.status = 'active' where u.status = 'active' and coalesce(p.service_announcements_enabled, 1) = 1
and m.tier = #{tier}
and u.id in #{id}
and 1 = 1
order by u.id

select count(*) from (


            select o.profile_id as id from cm_profile_ownerships o
            where o.user_id = #{userId} and o.profile_id = #{subjectId} and o.status = 'active'


            select r.event_id as id from cm_event_registrations r
            where r.user_id = #{userId} and r.event_id = #{subjectId}


            select r.id from cm_private_introduction_requests r
            where r.requester_user_id = #{userId} and r.id = #{subjectId}


            select m.id from cm_user_memberships m where m.user_id = #{userId} and m.id = #{subjectId}

        select null as id where 1 = 0

) access_subject

mapper.insert:
insert into cm_inbox_messages (
    id, thread_id, sender_type, sender_user_id, message_type, body,
    template_code, template_locale, action_type, action_payload, dedupe_key
) values (
    #{id}, #{threadId}, #{senderType}, #{senderUserId}, #{messageType}, #{body},
    #{templateCode}, #{templateLocale}, #{actionType}, null, #{dedupeKey}
)
